#include <vector>
#include <omp.h>

bool contains(std::vector<int> const& x, int target) {
  int found = 0; // use int for OpenMP reduction portability

  #pragma omp parallel for reduction(||:found)
  for (int i = 0; i < static_cast<int>(x.size()); ++i) {
    if (x[i] == target) found = 1;
  }

  return found != 0;
}
